assign o = {m_up1, m_down1, m_left1, m_right1, m_fire1, m_warp1, m_up2, m_down2, m_left2, m_right2, m_fire2, m_warp2,
            m_start1, m_start2, m_coin1, m_coin2, m_pause};
endmodule

/* verilator lint_off WIDTH */
/* verilator lint_off UNUSED */
/* verilator lint_off UNDRIVEN */
/* verilator lint_off MULTIDRIVEN */
module old_all(
    input         CLK_49M, pause_cpu,
    input  [10:0] ps2_key,
    input  [15:0] joystick_0, joystick_1,
    output [16:0] o
);
// ---- Arcade-JunoFirst.sv.orig lines 247-313
///////////////////         Keyboard           //////////////////

reg btn_up       = 0;
reg btn_down     = 0;
reg btn_left     = 0;
reg btn_right    = 0;
reg btn_fire     = 0;
reg btn_warp	 = 0;
reg btn_coin1    = 0;
reg btn_coin2    = 0;
reg btn_1p_start = 0;
reg btn_2p_start = 0;
reg btn_pause    = 0;
reg btn_service  = 0;

wire pressed = ps2_key[9];
wire [7:0] code = ps2_key[7:0];
always @(posedge CLK_49M) begin
	reg old_state;
	old_state <= ps2_key[10];
	if(old_state != ps2_key[10]) begin
		case(code)
			'h16: btn_1p_start <= pressed; // 1
			'h1E: btn_2p_start <= pressed; // 2
			'h2E: btn_coin1    <= pressed; // 5
			'h36: btn_coin2    <= pressed; // 6
			'h46: btn_service  <= pressed; // 9
			'h4D: btn_pause    <= pressed; // P

			'h75: btn_up      <= pressed; // up
			'h72: btn_down    <= pressed; // down
			'h6B: btn_left    <= pressed; // left
			'h74: btn_right   <= pressed; // right
			'h14: btn_fire    <= pressed; // ctrl
			'h11: btn_warp    <= pressed; // alt			
		endcase
	end
end

//////////////////  Arcade Buttons/Interfaces   ///////////////////////////

//Player 1 â 4-way movement joystick (D-pad / left stick)
wire m_up1      = btn_up      | joystick_0[3];
wire m_down1    = btn_down    | joystick_0[2];
wire m_left1    = btn_left    | joystick_0[1];
wire m_right1   = btn_right   | joystick_0[0];
wire m_fire1    = btn_fire    | joystick_0[4];
wire m_warp1    = btn_warp    | joystick_0[5];

//Player 2 â 4-way movement (second controller D-pad)
wire m_up2      = btn_up      | joystick_1[3];
wire m_down2    = btn_down    | joystick_1[2];
wire m_left2    = btn_left    | joystick_1[1];
wire m_right2   = btn_right   | joystick_1[0];
wire m_fire2    = btn_fire    | joystick_1[4];
wire m_warp2    = btn_warp    | joystick_1[5];

//Start/coin
wire m_start1   = btn_1p_start | joystick_0[6];   // Start button
wire m_start2   = btn_2p_start | joystick_0[7];   // R shoulder
wire m_coin1    = btn_coin1    | joystick_0[8];   // Select button
wire m_coin2    = btn_coin2;
wire m_pause    = btn_pause    | joystick_0[9];   // L shoulder (handled by framework)

// PAUSE SYSTEM
wire [23:0] rgb_out;
assign o = {m_up1, m_down1, m_left1, m_right1, m_fire1, m_warp1, m_up2, m_down2, m_left2, m_right2, m_fire2, m_warp2,
            m_start1, m_start2, m_coin1, m_coin2, m_pause};
endmodule

